LineComment.Text:

REGION 允许释放条件,根据实际完善
    //马达运行中且工位一允许进料
    IF "ST350_Motor_InterfaceDB".aDev[1].Run  THEN
        "ST350_Stopper_InterfaceDB".Command[1].In.iReleaseClear := TRUE;
    ELSE
        "ST350_Stopper_InterfaceDB".Command[1].In.iReleaseClear := FALSE;
    END_IF;
END_REGION

REGION IO_image
    //InPut
    "ST350_Stopper_InterfaceDB".Command[1].In.iSensor := "iBurfferPalletDetection";//本站托盘到位
    "ST350_Stopper_InterfaceDB".Command[1].In.iNextSensor := "iWork01PalletDetection";//后站托盘到位
    "ST350_Stopper_InterfaceDB".Command[1].In.iNextValve := "oA-Lifting-01StopperCylinder";//后站挡停输出

    // //OutPut
     "ST10Cylinder".Cy[5].Inout.AutoGoWork:= "ST350_Stopper_InterfaceDB".Command[1].Out.oValve;//本站挡停输出
END_REGION

REGION 允许释放条件,根据实际完善:顶升下降且线体运行中
    IF "ST10Cylinder".Cy[2].In.HomePositionSensor AND ("ST350_Motor_InterfaceDB".aDev[1].Run OR "Station_Sys".Manual.Mode) THEN//
        "ST350_Stopper_InterfaceDB".Command[2].In.iReleaseClear := True;
    ELSE
        "ST350_Stopper_InterfaceDB".Command[2].In.iReleaseClear := FALSE;
    END_IF;
END_REGION

REGION IO_image
    //InPut
    "ST350_Stopper_InterfaceDB".Command[2].In.iSensor := "iWork01PalletDetection";//本站托盘到位
    "ST350_Stopper_InterfaceDB".Command[2].In.iNextSensor := "iWork02PalletDetection";//后站托盘到位
    "ST350_Stopper_InterfaceDB".Command[2].In.iNextValve := "oA-Lifting-02StopperCylinder";//后站挡停输出

    // //OutPut
     "ST10Cylinder".Cy[1].Inout.AutoGoWork:= "ST350_Stopper_InterfaceDB".Command[2].Out.oValve;//本站挡停输出
END_REGION

*0

REGION IOimage
    //InPut
    "ST350_Stopper_InterfaceDB".Command[3].In.iSensor := "iWork02PalletDetection";//本站托盘到位
    "ST350_Stopper_InterfaceDB".Command[3].In.iNextSensor := "iD-LiftingDetection" AND NOT "iD-LiftingINDetection" ;//后站托盘到位

    //替换后站挡停释放信号：升降机在下&顶升下&无料&允许金托盘
    // "ST350_Stopper_InterfaceDB".Command[3].In.iNextValve := ;//后站挡停输出

    // //OutPut
     "ST10Cylinder".Cy[3].Inout.AutoGoWork := "ST350_Stopper_InterfaceDB".Command[3].Out.oValve;//本站挡停输出


END_REGION
